```openscad
// T-slot nut for aluminium extrusion
// Print orientation: flange down on XY plane, neck building up (+Z)

// ---------------- Parameters ----------------
nut_length      = 12;    // length along X (slot direction)
flange_width    = 12;    // bottom flange width (Y)
flange_thick    = 2.5;   // flange thickness (z = 0 to 2.5)
neck_width      = 7;     // neck width (Y), centred
total_height    = 5.5;   // top of neck (z)
hole_d          = 3.4;   // screw clearance hole diameter
cut_extra       = 0.5;   // overshoot for clean boolean cuts
$fn             = 64;    // circle resolution

// ---------------- Model ----------------
difference() {
    union() {
        // Bottom flange
        translate([-nut_length/2, -flange_width/2, 0])
            cube([nut_length, flange_width, flange_thick]);

        // Centred neck
        translate([-nut_length/2, -neck_width/2, 0])
            cube([nut_length, neck_width, total_height]);
    }

    // Vertical screw hole through the centre
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = total_height + 2*cut_extra, $fn = 64);
}
```

