```openscad
// Flat dial ring with radial tick marks for a rotary stage
// Units: mm. Prints flat on the bed, centred on origin.

$fn = 128;

// --- Ring dimensions ---
ring_od        = 70;    // outer diameter
ring_id        = 50;    // inner diameter
ring_thick     = 5;     // ring thickness (Z)

// --- Tick mark dimensions ---
tick_count     = 36;    // number of evenly spaced ticks
tick_width     = 1;     // groove width (tangential)
tick_depth     = 1.5;   // groove depth into top face
tick_length    = 3;     // radial length inward from outer edge
tick_start_ang = 0;     // first tick on +X axis (degrees)

// --- Helpers ---
eps            = 0.5;   // overshoot for clean boolean cuts

ring_or = ring_od / 2;
ring_ir = ring_id / 2;

difference() {
    // Annulus body
    difference() {
        cylinder(h = ring_thick, r = ring_or);
        translate([0, 0, -eps])
            cylinder(h = ring_thick + 2 * eps, r = ring_ir);
    }

    // Radial tick grooves in top face
    for (i = [0 : tick_count - 1]) {
        rotate([0, 0, tick_start_ang + i * 360 / tick_count])
            translate([ring_or - tick_length,
                       -tick_width / 2,
                       ring_thick - tick_depth])
                cube([tick_length + eps,          // runs past outer edge
                      tick_width,
                      tick_depth + eps]);         // runs past top face
    }
}
```

