    // Annulus body
    difference() {
        cylinder(h = ring_h, r = outer_r);
        translate([0, 0, -eps])
            cylinder(h = ring_h + 2 * eps, r = inner_r);
    }

    // Radial tick grooves in the top face
    for (i = [0 : tick_count - 1])
        rotate([0, 0, start_angle + i * 360 / tick_count])
            translate([outer_r - tick_len, -tick_w / 2, ring_h - tick_depth])
                cube([tick_len + overshoot, tick_w, tick_depth + eps + 0.5]);
