```openscad
// Stiffened cover panel: flat plate with 4 transverse ribs
// Print orientation: plate on bed (z = 0), ribs build upward

// ---------- Parameters ----------
plate_len   = 120;   // plate length along X (mm)
plate_wid   = 60;    // plate width along Y (mm)
plate_thk   = 2;     // plate thickness (mm), z = 0..2

rib_count   = 4;     // number of ribs
rib_thk     = 3;     // rib thickness along X (mm)
rib_h       = 6;     // rib height above plate (mm), z = 2..8
rib_pitch   = plate_len / (rib_count + 1);  // 24 mm centre spacing
overlap     = 0.01;  // small overlap so ribs fuse into plate

// ---------- Model ----------
union() {
    // Base plate, centred in X and Y
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs: centres at -36, -12, 12, 36 mm
    for (i = [1 : rib_count]) {
        x_c = -plate_len/2 + i * rib_pitch;
        translate([x_c - rib_thk/2, -plate_wid/2, plate_thk - overlap])
            cube([rib_thk, plate_wid, rib_h + overlap]);
    }
}
```

