// Stiffened cover panel
// Units: mm. Print orientation: plate on bed, ribs up.

plate_len   = 120;  // plate length along X
plate_wid   = 60;   // plate width along Y
plate_thk   = 2;    // plate thickness (z = 0 to 2)

rib_count   = 4;    // number of ribs
rib_thk     = 2;    // rib thickness along X
rib_h       = 6;    // rib height above plate (z = 2 to 8)
rib_pitch   = 24;   // centre-to-centre spacing of ribs
overlap     = 0.01; // small overlap so ribs fuse with plate

$fn = 64;

union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, centred about origin: x = -36, -12, 12, 36
    for (i = [0 : rib_count - 1]) {
        x_c = (i - (rib_count - 1)/2) * rib_pitch;
        translate([x_c - rib_thk/2, -plate_wid/2, plate_thk - overlap])
            cube([rib_thk, plate_wid, rib_h + overlap]);
    }
}
