// Star-shaped indexing wheel
// Flat 6-pointed star plate with a centre hole

// ---------------- Parameters ----------------
n_points   = 6;      // number of star points
r_outer    = 35;     // radius of outer (tip) points [mm]
r_inner    = 17.5;   // radius of inner (valley) points [mm]
thickness  = 3;      // plate thickness [mm]
hole_d     = 6;      // centre hole diameter [mm]
eps        = 0.5;    // cutting overlap past faces [mm]
$fn        = 96;     // resolution for curved shapes

// ---------------- Star outline ----------------
// Alternating outer/inner vertices, first outer point on +X axis
star_pts = [
    for (i = [0 : 2 * n_points - 1])
        let (
            a = i * 180 / n_points,
            r = (i % 2 == 0) ? r_outer : r_inner
        )
        [r * cos(a), r * sin(a)]
];

// ---------------- Model ----------------
difference() {
    // Star plate resting on the bed
    linear_extrude(height = thickness)
        polygon(points = star_pts);

    // Centre hole (extends past top and bottom faces)
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps, $fn = 96);
}
