// Square frustum built by hulling two thin square slabs
module frustum(b, t, h) {
    hull() {
        translate([-b/2, -b/2, 0])
            cube([b, b, 0.01]);
        translate([-t/2, -t/2, h - 0.01])
            cube([t, t, 0.01]);
    }
}

difference() {
    frustum(base_size, top_size, block_height);

    // Top pocket, extends past the top face
    translate([-pocket_size/2, -pocket_size/2, block_height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
