rim_ir = rim_or - rim_width;
hub_r  = hub_d / 2;
spoke_len = rim_ir - hub_r;  // span between hub and rim

// ---- Model ----
difference() {
    union() {
        // Rim ring
        difference() {
            cylinder(h = thickness, r = rim_or);
            translate([0, 0, -eps])
                cylinder(h = thickness + 2 * eps, r = rim_ir);
        }

        // Hub
        cylinder(h = thickness, r = hub_r);

        // Spokes (first along +X), overlapping into hub and rim
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([hub_r - 1, -spoke_width / 2, 0])
                    cube([spoke_len + 2, spoke_width, thickness]);
    }

    // Axle hole
    translate([0, 0, -eps])
        cylinder(h = thickness + 2 * eps, d = axle_d);
}
