thickness      = 5;    // overall wheel thickness (Z)
rim_od         = 60;   // rim outer diameter
rim_width      = 4;    // rim radial width
rim_id         = rim_od - 2*rim_width; // rim inner diameter (52)
hub_d          = 14;   // hub outer diameter
axle_d         = 6;    // axle hole diameter
spoke_count    = 4;    // number of spokes
spoke_width    = 5;    // spoke width
spoke_start_angle = 0; // first spoke along +X

eps = 0.5;             // cutter overshoot

// ---- Model ----
difference() {
    union() {
        // Rim
        difference() {
            cylinder(d = rim_od, h = thickness);
            translate([0, 0, -eps])
                cylinder(d = rim_id, h = thickness + 2*eps);
        }

        // Hub
        cylinder(d = hub_d, h = thickness);

        // Spokes (overlap into hub and rim for a solid union)
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, spoke_start_angle + i * 360 / spoke_count])
                translate([hub_d/4, -spoke_width/2, 0])
                    cube([(rim_od/2 - rim_width/2) - hub_d/4, spoke_width, thickness]);
    }

    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2*eps);
